import heapq, math
import numpy as np
from PIL import Image,ImageDraw
from scipy import ndimage
im=np.array(Image.open('/app/target.png').convert('RGB')); mask=(im.mean(2)<100)
def sh(a,dy,dx): return np.roll(np.roll(a,dy,0),dx,1)
sk=mask.copy()
while True:
 nrem=0
 for phase in [0,1]:
  p2=sh(sk,-1,0);p3=sh(sk,-1,1);p4=sh(sk,0,1);p5=sh(sk,1,1);p6=sh(sk,1,0);p7=sh(sk,1,-1);p8=sh(sk,0,-1);p9=sh(sk,-1,-1)
  ns=[p2,p3,p4,p5,p6,p7,p8,p9];B=sum(ns); A=sum((~ns[i]&ns[(i+1)%8]) for i in range(8))
  c1=~(p2&p4&p6) if phase==0 else ~(p2&p4&p8)
  c2=~(p4&p6&p8) if phase==0 else ~(p2&p6&p8)
  r=sk&(B>=2)&(B<=6)&(A==1)&c1&c2;r[[0,-1]]=False;r[:,[0,-1]]=False
  nrem+=r.sum();sk[r]=False
 if nrem==0:break
labs,n=ndimage.label(mask,structure=np.ones((3,3))); dist=ndimage.distance_transform_edt(mask)
coords_by_comp={k:[tuple(x) for x in np.argwhere(sk&(labs==k))] for k in range(1,n+1)}
coords_set={k:set(v) for k,v in coords_by_comp.items()}
def nearest(k,xy):
 u,v=xy; return min(coords_by_comp[k],key=lambda yx:(yx[1]-u)**2+(yx[0]-v)**2)
def path(k,a,b):
 s=nearest(k,a);g=nearest(k,b)
 if s==g:return [s]
 q=[(0,s)]; cost={s:0}; prev={}
 while q:
  d,u=heapq.heappop(q)
  if u==g:break
  if d!=cost[u]:continue
  y,x=u
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if not(dx or dy):continue
    v=(y+dy,x+dx)
    if v not in coords_set[k]:continue
    nd=d+(1.41421356 if dx and dy else 1)
    if nd<cost.get(v,1e99):cost[v]=nd;prev[v]=u;heapq.heappush(q,(nd,v))
 if g not in cost: raise ValueError((k,a,b,s,g))
 out=[g]
 while out[-1]!=s:out.append(prev[out[-1]])
 return out[::-1]
def join(k, anchors):
 pts=[]
 for a,b in zip(anchors,anchors[1:]):
  z=path(k,a,b)
  pts+=z if not pts else z[1:]
 return np.array(pts)
routes=[]
routes.append(('upperleft',2,join(2,[(379,235),(273,398)])))
routes.append(('leftbranched',3,join(3,[(362,378),(323,518),(205,622),(323,518),(338,760)])))
routes.append(('rightnetwork',1,join(1,[(567,214),(477,329),(673,306),(556,397),(434,410),(474,530),(684,508),(732,410),(556,397),(526,410),(533,508),(600,499),(608,400),(684,508)])))
for k,a,b,name in [(4,(480,571),(658,561),'bar'),(5,(687,589),(777,653),'rightdot'),(6,(564,611),(608,650),'middledot'),(7,(426,631),(399,719),'leftdot'),(8,(479,631),(678,661),'hooka'),(8,(678,661),(737,746),'hookb')]:
 if name=='hooka': hookpath=path(k,a,b)
 elif name=='hookb': hookpath+=path(k,a,b)[1:]
 elif name=='bar': routes.append((name,k,join(k,[a,b])))
 elif name=='rightdot':routes.append((name,k,join(k,[a,b])))
 elif name=='middledot':routes.append((name,k,join(k,[a,b])))
 elif name=='leftdot':routes.append((name,k,join(k,[a,b])))
routes.append(('hook',8,np.asarray(hookpath)))
# Mask predicted via circular brush footprint from the local EDT.
pred=Image.new('1',(1024,1024)); dr=ImageDraw.Draw(pred)
route_coords=[]
for name,k,pts in routes:
 # smooth with gaussian sigma 1.4 pixel, no cross-component smoothing at endpoints
 xy=pts[:,::-1].astype(float)
 xy[:,0]=ndimage.gaussian_filter1d(xy[:,0],1.5,mode='nearest')
 xy[:,1]=ndimage.gaussian_filter1d(xy[:,1],1.5,mode='nearest')
 # rasterize points every 1.5 px; widths interpolated from nearby target distance field
 for i in range(0,len(xy),2):
  u,v=xy[i]; ru,rv=int(round(u)),int(round(v)); radius=float(dist[rv,ru])
  dr.ellipse((u-radius,v-radius,u+radius,v+radius),fill=1)
 # connect circles also via line at local width
 # Report route endpoints/length/coverage
 print(name,'comp',k,'nodes',len(pts),'lenpx',round(np.linalg.norm(np.diff(pts,axis=0),axis=1).sum(),1),'startend',pts[0,::-1],pts[-1,::-1])
pred=np.array(pred,dtype=bool); inter=np.logical_and(pred,mask).sum(); union=np.logical_or(pred,mask).sum()
print('target',mask.sum(),'pred',pred.sum(),'inter',inter,'iou',inter/union,'extraneous',np.logical_and(pred,~mask).sum()/mask.sum(),'miss',np.logical_and(~pred,mask).sum()/mask.sum())
out=im.copy(); out[pred & ~mask]=[220,30,30];out[mask & ~pred]=[30,80,230];out[pred&mask]=[20,140,50]
Image.fromarray(out).save('/app/output/path_pred.png')
